mod lesson_tests {
    use super::*;
    #[test]
    fn contract() {
use std::{sync::{Arc,atomic::{AtomicUsize,Ordering}},task::{Wake,Waker}};
struct Count(AtomicUsize); impl Wake for Count { fn wake(self:Arc<Self>) { self.0.fetch_add(1,Ordering::Relaxed); } }
let counter=Arc::new(Count(AtomicUsize::new(0))); let w=Waker::from(counter.clone()); let mut cx=Context::from_waker(&w);
let mut f=Box::pin(YieldOnce(false)); assert_eq!(f.as_mut().poll(&mut cx),Poll::Pending);
assert_eq!(counter.0.load(Ordering::Relaxed),1); assert_eq!(f.as_mut().poll(&mut cx),Poll::Ready(7));
    }
}

