fn checked(xs:&[u32],index:usize)->Option<&u32> {
    if index < xs.len() {
        // SAFETY: the guard proves the index is in bounds; xs supplies a live shared borrow.
        Some(unsafe { xs.get_unchecked(index) })
    } else { None }
}
fn main() {}

