fn find(xs:&[i32],target:i32)->(bool,usize) {
    let (mut lo,mut hi,mut count)=(0,xs.len(),0);
    while lo < hi {
        let mid=lo+(hi-lo)/2; count+=1;
        match xs[mid].cmp(&target) {
            std::cmp::Ordering::Less => lo=mid+1,
            std::cmp::Ordering::Greater => hi=mid,
            std::cmp::Ordering::Equal => return (true,count),
        }
    }
    (false,count)
}
fn main() {}

